import numpy as np
import sys
sys.path.insert(0, '.')
from annot_sensitivity.asv import compute_asv
from annot_sensitivity.confusion import delta_range

# Same matrices
C_list_raw = {
    'C1_sym': np.array([[0.80, 0.10, 0.10],[0.10, 0.80, 0.10],[0.10, 0.10, 0.80]]),
    'C2_high': np.array([[0.90, 0.05, 0.05],[0.05, 0.90, 0.05],[0.05, 0.05, 0.90]]),
    'C3_asym': np.array([[0.70, 0.20, 0.10],[0.15, 0.70, 0.15],[0.10, 0.15, 0.75]]),
    'C4_weak': np.array([[0.60, 0.20, 0.20],[0.20, 0.60, 0.20],[0.15, 0.15, 0.70]]),
    'C5_perm': np.array([[0.40, 0.30, 0.30],[0.30, 0.40, 0.30],[0.30, 0.30, 0.40]]),
    'C6_diff': np.array([[0.85, 0.075, 0.075],[0.15, 0.70, 0.15],[0.05, 0.05, 0.90]]),
}
C_list = {}
for name, C in C_list_raw.items():
    C = np.maximum(C, 0.0)
    cs = C.sum(axis=0)
    cs = np.where(cs < 1e-10, 1.0, cs)
    C_list[name] = C / cs

# Compute ranges per topology for magnitude ASV
topologies = ['confounding', 'mediation', 'collider', 'iv', 'frontdoor', 'mbias', 'exposure']

for topo in topologies:
    mag_asvs = []
    sf_asvs = []
    for cname, C0 in C_list.items():
        try:
            r = compute_asv(topo, C0, threshold_type='magnitude')
            if r['asv'] is not None:
                mag_asvs.append((cname, r['asv']))
        except:
            pass
        try:
            r = compute_asv(topo, C0, threshold_type='sign_flip')
            if r['asv'] is not None:
                sf_asvs.append((cname, r['asv']))
        except:
            pass

    if mag_asvs:
        vals = [v for _, v in mag_asvs]
        print(f'{topo:12s} magnitude: {min(vals):.3f}--{max(vals):.3f}  (from {len(mag_asvs)} matrices)')
    else:
        print(f'{topo:12s} magnitude: None')
    if sf_asvs:
        vals = [v for _, v in sf_asvs]
        print(f'{topo:12s} sign_flip: {min(vals):.3f}--{max(vals):.3f}  (from {len(sf_asvs)} matrices)')
